Translate("esMX", "dun-morogh", {
	title = "Dun Morogh",
	sections = {
		{
			title = "Resumen",
			text = [=[Dun Morogh es una tierra de nieve y piedra en el oeste de Khaz Modan, la antigua patria de los {link:dwarves}enanos{/link}. Sus cumbres son las más altas de los {link:eastern-kingdoms}Reinos del Este{/link}, y dentro de la mayor de ellas se encuentra {link:ironforge}Forjaz{/link}, la capital del {link:kingdom-of-ironforge}Reino de Forjaz{/link}. Los {link:gnomes}gnomos{/link} también vivieron aquí, en la ciudad de {link:gnomeregan}Gnomeregan{/link}, bajo las colinas del oeste. Entre las dos ciudades hay lagos helados, pinares y un único y largo camino a través de la nieve. Es un país duro, y su gente está orgullosa de él.]=],
		},
		{
			title = "Orígenes",
			text = [=[Los enanos dicen que fueron moldeados con la piedra de estas montañas en eras pasadas, y que {link:ironforge}Forjaz{/link} es su hogar más antiguo. Hace mucho, todos los enanos eran gobernados desde allí por un único gran rey. Cuando ese rey murió, los clanes Barbabronce, Martillo Salvaje y {link:dark-iron-dwarves}Hierro Negro{/link} fueron a la guerra por su trono, y los Barbabronce conservaron la montaña. Los gnomos llegaron a ser vecinos y amigos de los enanos, y levantaron {link:gnomeregan}Gnomeregan{/link} en las estribaciones occidentales. Ninguna crónica registra el año en que se fundó cualquiera de las dos ciudades.]=],
		},
		{
			title = "El presente",
			text = [=[Dun Morogh es menos segura de lo que ha sido en la memoria de los vivos. Gran parte del ejército del rey está lejos, sirviendo a la {link:alliance}Alianza{/link} en el extranjero, y los montañeros que quedan son pocos. Los {link:troggs}troggs{/link} han brotado de los lugares profundos, y ahora ocupan el Desfiladero de {link:coldridge-valley}Crestanevada{/link} y los fosos de la {link:gol-bolar-quarry}Cantera de Gol'Bolar{/link}. Los {link:frostmane-trolls}trols Peloescarcha{/link} ocupan sus cuevas y crestas en el oeste. {link:gnomeregan}Gnomeregan{/link} está perdida, y su pueblo envenenado vaga ante sus puertas. Los wendigos han llenado {link:the-grizzled-den}El Cubil Pardo{/link}. Lo más inquietante de todo es que se han visto espías del {link:dark-iron-dwarves}clan Hierro Negro{/link} en el este, con mapas de túneles que llevan bajo la propia {link:ironforge}Forjaz{/link}.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}Los enanos de {link:ironforge}Forjaz{/link}.{/b} Mineros, cerveceros, criadores de carneros y montañeros, viven en {link:kharanos}Kharanos{/link}, {link:brewnall-village}Las Birras{/link} y los campamentos solitarios de las tierras altas.
• {b}Los gnomos de {link:gnomeregan}Gnomeregan{/link}.{/b} Los supervivientes de su ciudad caída se refugian en Forjaz, y algunos trabajan en Kharanos para deshacer el daño que se hizo.
• {b}Los {link:frostmane-trolls}trols Peloescarcha{/link}.{/b} Ocupan cuevas y crestas en el oeste y disputan las nieves a los enanos.
• {b}Los troggs.{/b} Los troggs Rockjaw surgieron de debajo de la tierra y ahora atacan allí donde los enanos excavan.
• {b}Los wendigos y las bestias.{/b} Wendigos, osos, jabalíes y leopardos de las nieves recorren las colinas, y algunos se han vuelto demasiado audaces y demasiado grandes.
• {b}Los {link:dark-iron-dwarves}Hierro Negro{/link}.{/b} Una banda de ellos ocupa el {link:ironband-s-compound}Complejo Vetaferro{/link} en el este, vigilando y esperando.]=],
		},
		{
			title = "Historia",
			text = [=[• {b}Los Tres Martillos.{/b} En la guerra de los tres clanes, los Barbabronce conservaron {link:ironforge}Forjaz{/link} y expulsaron a sus rivales. Un tratado guardado bajo la ciudad registra que los Martillo Salvaje firmaron la paz, y los {link:dark-iron-dwarves}Hierro Negro{/link} no.
• {b}La {link:second-war}Segunda Guerra{/link}.{/b} Cuando la {link:horde}Horda{/link} invadió Khaz Modan, la propia Forjaz resistió. Los enanos se unieron a la {link:alliance}Alianza de Lordaeron{/link} y lucharon junto a los humanos hasta que la Horda fue derrotada.
• {b}La caída de {link:gnomeregan}Gnomeregan{/link}.{/b} Los troggs surgieron bajo la ciudad gnómica. Los gnomos lucharon para expulsarlos, pero el arma que usaron envenenó la ciudad y a muchos de los suyos. Los supervivientes huyeron a Forjaz.
• {b}El presente.{/b} Ahora los enanos se enfrentan a la vez a troggs, trols y Hierro Negro, con la mitad de sus fuerzas lejos, en la guerra.]=],
		},
		{
			title = "Saber de las montañas",
			text = [=[• Los Thunderbrew de {link:kharanos}Kharanos{/link} y los Barleybrew de {link:brewnall-village}Las Birras{/link} son familias cerveceras rivales. Cada una cree que la cerveza de la otra solo sirve para los jabalíes.
• Los {link:frostmane-trolls}trols Peloescarcha{/link} cultivan una hierba pálida llamada brillohierba en las crestas sobre el {link:iceflow-lake}Lago Glacial{/link}, y la usan en sus rituales. Los enanos le han encontrado un uso mejor: la cerveza negra.
• Los montañeros de {link:ironforge}Forjaz{/link} graban sus nombres en las culatas de sus rifles, para que la nieve pueda decir a quién se ha llevado.
• Los ladrones de Forjaz susurran que los tanques de vapor blindados del rey llevan mineral y gemas desde la {link:gol-bolar-quarry}Cantera de Gol'Bolar{/link} por un camino extrañamente enrevesado, y que alguien debería aliviarle de un poco de ello.]=],
		},
	},
})

Translate("esMX", "coldridge-valley", {
	title = "Valle de Crestanevada",
	aliases = { "Crestanevada" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Valle de Crestanevada es un valle resguardado en el suroeste de {link:dun-morogh}Dun Morogh{/link}, cerrado por montañas por todos lados. Los nuevos defensores de {link:ironforge}Forjaz{/link} vienen aquí a aprender su oficio en Yunquemar. El valle ha perdido su paz. Los troggs Rockjaw arrasaron el campamento del oeste y pululan por las colinas junto al lago helado. Los {link:frostmane-trolls}trols Peloescarcha{/link} ocupan una cueva en el sur. El único camino de salida, por el túnel del Desfiladero de Crestanevada, está ahora lleno de troggs, y un montañero vigila su boca.]=],
		},
	},
})

Translate("esMX", "anvilmar", {
	title = "Yunquemar",
	sections = {
		{
			title = "Resumen",
			text = [=[Yunquemar es una morada excavada en lo hondo de la ladera, en la cabecera del {link:coldridge-valley}Valle de Crestanevada{/link}. Aquí los instructores de {link:ironforge}Forjaz{/link} enseñan a los jóvenes a luchar, rezar y ejercer su oficio, y los proveedores les dan ropa de abrigo contra el frío. También es un refugio. {link:gnomes}Gnomos{/link} que huyeron del veneno de {link:gnomeregan}Gnomeregan{/link} han encontrado cobijo en sus salas, y algunos todavía cuentan lo que perdieron por el camino.]=],
		},
	},
})

Translate("esMX", "kharanos", {
	title = "Kharanos",
	aliases = { "Destilería Cebatruenos" },
	sections = {
		{
			title = "Resumen",
			text = [=[Kharanos es la principal población de {link:dun-morogh}Dun Morogh{/link}, un grupo de casas de piedra en el camino entre {link:coldridge-valley}Crestanevada{/link} y {link:ironforge}Forjaz{/link}. En su corazón se alza la Destilería Cebatruenos, famosa en todo Khaz Modan, cuyas bodegas están repletas de barriles de cerveza del trueno. La taberna rara vez está tranquila. Los montañeros se presentan aquí, y {link:senir-whitebeard}Senir Whitebeard{/link} escribe sus informes para el Senado de Forjaz. Dos gnomos de la población trabajan en una máquina que esperan que cure a su pueblo.]=],
		},
	},
})

Translate("esMX", "steelgrill-s-depot", {
	title = "Almacén de Brasacerada",
	aliases = { "Almacén Brasacerada" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Almacén de Brasacerada se encuentra justo al nordeste de {link:kharanos}Kharanos{/link}. Es el taller de {link:beldin-steelgrill}Beldin Steelgrill{/link}, el mejor mecánico de máquinas de asedio de las montañas, y un lugar frecuentado por los pilotos de la Brigada de Asedio. Sus tanques de vapor blindados llevan nombres como Jetsteam y Trollplow, y sus pilotos presumen de ellos como otros enanos presumen de sus carneros. El almacén se entera de mucho de lo que pasa por los caminos, y fue el informe de un montañero aquí lo que primero atrajo las miradas hacia una extraña hoguera sobre {link:gol-bolar-quarry}Gol'Bolar{/link}.]=],
		},
	},
})

Translate("esMX", "the-grizzled-den", {
	title = "El Cubil Pardo",
	aliases = { "Cubil Pardo" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Cubil Pardo es una cueva en las colinas al oeste de {link:kharanos}Kharanos{/link}. Sus túneles fueron una rica fuente de mineral, y los mineros de Kharanos trabajaban allí. Entonces los wendigos se extendieron desde sus propias cuevas y la llenaron. Los mineros huyeron y dejaron atrás sus cargamentos. Un montañero llamado Cornelius entró para ver lo mal que estaban las cosas y nunca salió. En lo más hondo mora un wendigo ruidoso y salvaje llamado Frosthowl.]=],
		},
	},
})

Translate("esMX", "chill-breeze-valley", {
	title = "Valle Escalofrío",
	sections = {
		{
			title = "Resumen",
			text = [=[El Valle Escalofrío se abre en el oeste de {link:dun-morogh}Dun Morogh{/link}, entre {link:kharanos}Kharanos{/link} y las colinas de {link:gnomeregan}Gnomeregan{/link}. Su tramo oriental es muy transitado, pues el camino del Desfiladero de {link:coldridge-valley}Crestanevada{/link} lo atraviesa. Pocos van por gusto a sus rincones más tranquilos. Allí, un gran wendigo llamado Old Icebeard tiene una cueva, y una vez se llevó toda la despensa de carne del trampero Tundra MacGrann, que acampa cerca con una pierna mala y el estómago vacío.]=],
		},
	},
})

Translate("esMX", "brewnall-village", {
	title = "Las Birras",
	aliases = { "Birras" },
	sections = {
		{
			title = "Resumen",
			text = [=[Las Birras se encuentra en la orilla oeste del {link:iceflow-lake}Lago Glacial{/link}. Es el hogar de la familia Barleybrew, cerveceros que experimentan sin miedo y a veces sin éxito. Su Evershine arde con tanta fuerza que los pilotos de asedio la vierten en sus hornos. Los Barleybrew no sienten ningún aprecio por los Thunderbrew de {link:kharanos}Kharanos{/link}, y no les importa hacer alguna travesura en la bodega de sus rivales. Los pescadores faenan en {link:the-loch}el lago{/link} junto a ellos, y los {link:frostmane-trolls}trols Peloescarcha{/link} vigilan desde el suroeste.]=],
		},
	},
})

Translate("esMX", "iceflow-lake", {
	title = "Lago Glacial",
	sections = {
		{
			title = "Resumen",
			text = [=[El Lago Glacial se extiende por el norte de {link:dun-morogh}Dun Morogh{/link}, al oeste de {link:ironforge}Forjaz{/link}, helado durante gran parte del año. Un río de hielo baja hasta él desde el puente al norte de {link:kharanos}Kharanos{/link}. Los lobos cazan en la isla de su centro. Los pescadores de {link:brewnall-village}Las Birras{/link} abren agujeros en el hielo y esperan días enteros junto a sus sedales, y maldicen a los wendigos que roban lo poco que pescan.]=],
		},
	},
})

Translate("esMX", "frostmane-hold", {
	title = "Poblado Peloescarcha",
	sections = {
		{
			title = "Resumen",
			text = [=[El Poblado Peloescarcha es la gran cueva de los {link:frostmane-trolls}trols Peloescarcha{/link}, al suroeste de {link:brewnall-village}Las Birras{/link}. Cazadores de cabezas, desolladores, zancudos de las nieves y lanzadores de sombras moran allí en tal número que asustaron incluso al {link:dwarves}enano{/link} enviado a contarlos. El Poblado es el corazón del poder Peloescarcha en {link:dun-morogh}Dun Morogh{/link}. Los enanos han intentado averiguar lo que los trols planean dentro, y sus informes han causado tantos problemas en el Senado como en la nieve.]=],
		},
	},
})

Translate("esMX", "shimmer-ridge", {
	title = "Monte Luz",
	sections = {
		{
			title = "Resumen",
			text = [=[El Monte Luz es una cadena de colinas altas en el norte de {link:dun-morogh}Dun Morogh{/link}, cerca del {link:iceflow-lake}Lago Glacial{/link} y al oeste de las Puertas de {link:ironforge}Forjaz{/link}. Los {link:frostmane-trolls}trols Peloescarcha{/link} tienen campamentos en ella, unidos por un puente, y sus videntes cuidan allí cestas de brillohierba. La hierba tiene algún papel en sus ritos. Para los cerveceros de {link:brewnall-village}Las Birras{/link} tiene otro propósito, y pagan bien a quien suba a la cresta a robarla.]=],
		},
	},
})

Translate("esMX", "gates-of-gnomeregan", {
	title = "Puertas de Gnomeregan",
	sections = {
		{
			title = "Resumen",
			text = [=[Al norte de {link:brewnall-village}Las Birras{/link}, las colinas del oeste de {link:dun-morogh}Dun Morogh{/link} se alzan hasta las puertas de {link:gnomeregan}Gnomeregan{/link}. Antaño era una tierra bulliciosa de máquinas y aldeas gnómicas. Ahora las bombas y los filtros están rotos, y los gnomos que quedan están envenenados, enfermos y hostiles, y vagan ante las puertas de la ciudad que no pudieron salvar. Entre ellos se oculta disfrazado un espía {link:dwarves}enano{/link} de turbias intenciones. Los gnomos que huyeron dicen que valiosos registros de su pueblo siguen enterrados aquí, en la nieve.]=],
		},
	},
})

Translate("esMX", "gol-bolar-quarry", {
	title = "Cantera de Gol'Bolar",
	aliases = { "Gol'Bolar" },
	sections = {
		{
			title = "Resumen",
			text = [=[La Cantera de Gol'Bolar es un gran foso abierto en el este de {link:dun-morogh}Dun Morogh{/link}, donde los mineros del rey extraen mineral y piedra. Cuando excavaron hondo, los troggs Rockjaw salieron en tropel de la roca, destrozaron las máquinas y expulsaron a los mineros del foso. Ahora el capataz está furioso, un senador de {link:ironforge}Forjaz{/link} paga por cabezas de {link:troggs}trogg{/link} y el maestro de cantera espera que nadie se entere de que los troggs se llevaron su pólvora. Desde Las Colinas Tundra, arriba, un forastero Martillo Salvaje lo vigila todo.]=],
		},
	},
})

Translate("esMX", "amberstill-ranch", {
	title = "Granja de Semperámbar",
	sections = {
		{
			title = "Resumen",
			text = [=[La Granja de Semperámbar se encuentra junto al camino al este de {link:kharanos}Kharanos{/link}. La familia Amberstill cría los grandes carneros de montaña que llevan a los enanos de {link:ironforge}Forjaz{/link}, y sus rebaños son el orgullo de {link:dun-morogh}Dun Morogh{/link}. Los carneros de la granja van ahora a la expedición de {link:alterac-mountains}Alterac{/link}, y necesitan sillas de las mejores pieles de leopardo. El rebaño también tiene su propio cazador: la bestia {link:vagash}Vagash{/link}, que tiene su guarida en las laderas de arriba y baja de noche.]=],
		},
	},
})

Translate("esMX", "misty-pine-refuge", {
	title = "Refugio Pinobruma",
	sections = {
		{
			title = "Resumen",
			text = [=[El Refugio Pinobruma es una casa solitaria en las colinas del norte de {link:dun-morogh}Dun Morogh{/link}, al este de las Puertas de {link:ironforge}Forjaz{/link}. El padre {link:father-gavin}Gavin{/link} del {link:argent-dawn}Alba Argenta{/link} la ha reparado y mantiene su hogar encendido para cualquier viajero sorprendido por el frío. Las montañas que la rodean se han vuelto peligrosas. Un desprendimiento de las cumbres ha despertado espíritus de hielo, y el mayor de ellos parece traer tormentas y nuevos desprendimientos allá donde va.]=],
		},
	},
})

Translate("esMX", "helm-s-bed-lake", {
	title = "Lago de Helm",
	sections = {
		{
			title = "Resumen",
			text = [=[El Lago de Helm se encuentra en el extremo sureste de {link:dun-morogh}Dun Morogh{/link}, cerca de los pasos hacia {link:loch-modan}Loch Modan{/link}. Su agua está casi toda helada, y la tierra de su alrededor es salvaje y vacía. Los troggs Rockjaw recorren sus orillas. En las colinas del norte, un piloto de asedio espera junto a dos máquinas a un amigo que siguió solo en busca de un mineral raro. El amigo era Mori Hildelve, y un gran oso llamado Mangeclaw lo encontró primero.]=],
		},
	},
})

Translate("esMX", "ironband-s-compound", {
	title = "Complejo Vetaferro",
	sections = {
		{
			title = "Resumen",
			text = [=[El Complejo Vetaferro es una casa con patio al sur del {link:helm-s-bed-lake}Lago de Helm{/link}, en el este de {link:dun-morogh}Dun Morogh{/link}. Sus dueños enanos lo han abandonado. Ahora lo ocupan enanos {link:dark-iron-dwarves}Hierro Negro{/link}, dirigidos por un capitán llamado Beld, y atacan a cualquiera que se acerque. El vidente de la tierra {link:earthseer-farsen}Farsen{/link}, un Martillo Salvaje, cree que no son simples saqueadores. Los mapas tomados de sus muertos muestran túneles que corren muy bajo tierra y se unen bajo {link:ironforge}Forjaz{/link}.]=],
		},
	},
})

Translate("esMX", "frostmane-trolls", {
	title = "Trols Peloescarcha",
	aliases = { "Peloescarcha", "trols Peloescarcha", "tribu Peloescarcha" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Peloescarcha son una tribu de {link:trolls}trols{/link} que vive en las nieves de {link:dun-morogh}Dun Morogh{/link}. Son fieros y reservados, y disputan estas montañas a los enanos. Ninguna crónica registra cuándo llegaron aquí.]=],
		},
		{
			title = "Sus tierras",
			text = [=[Su mayor bastión es el {link:frostmane-hold}Poblado Peloescarcha{/link}, una caverna al suroeste de {link:brewnall-village}Las Birras{/link}. También tienen campamentos en el {link:shimmer-ridge}Monte Luz{/link} y una cueva en el sur del {link:coldridge-valley}Valle de Crestanevada{/link}, donde viven las crías de la tribu. Sus guerreros son cazadores de cabezas y zancudos de las nieves. Sus videntes y lanzadores de sombras practican una magia propia, y recogen brillohierba para sus rituales.]=],
		},
		{
			title = "En el presente",
			text = [=[El Senado de {link:ironforge}Forjaz{/link} ya tiene bastante con los troggs, y preferiría no pensar en los trols en absoluto. Dos hermanos de la familia Whitebeard fueron enviados a averiguar cuán grande es de verdad la amenaza. {link:grelin-whitebeard}Grelin{/link} juzgó que los trols de {link:coldridge-valley}Crestanevada{/link} eran pocos. {link:senir-whitebeard}Senir{/link} encontró el {link:frostmane-hold}Poblado Peloescarcha{/link} lleno de ellos. Entre los dos informes queda la pregunta de cuánto pueden permitirse ignorar los enanos. En Crestanevada, un trol llamado {link:grik-nir-the-cold}Grik'nir el Frío{/link} ha robado a los enanos algo más que un diario: les ha mostrado que los Peloescarcha los vigilan.]=],
		},
	},
})

Translate("esMX", "gnomeregan-exiles", {
	title = "Exiliados de Gnomeregan",
	aliases = { "exiliados de Gnomeregan" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Exiliados de Gnomeregan son los gnomos que sobrevivieron a la caída de su ciudad. Son un pueblo sin hogar. La mayoría vive en {link:ironforge}Forjaz{/link}, donde el rey {link:magni-bronzebeard}Magni Bronzebeard{/link} les dio espacio en {link:tinker-town}Tinker Town{/link}, pero están dispersos por {link:dun-morogh}Dun Morogh{/link} y más allá.]=],
		},
		{
			title = "Tras la caída",
			text = [=[Los troggs surgieron bajo {link:gnomeregan}Gnomeregan{/link}, y los gnomos los hicieron retroceder con un arma de su propia invención. Salió terriblemente mal. La ciudad quedó envenenada, y muchos de sus habitantes se convirtieron en parias enfermos y sin juicio que todavía vagan ante sus puertas. Los demás huyeron a la nieve con lo que pudieron cargar. Algunos lo perdieron todo a manos de los trols por el camino. Otros dejaron atrás los registros de sus familias, sus inventos y su oficio.]=],
		},
		{
			title = "En el presente",
			text = [=[Los exiliados no se han rendido. En {link:kharanos}Kharanos{/link}, {link:razzle-sprysprocket}Razzle Sprysprocket{/link} y Ozzie Togglevolt construyen una máquina que esperan que devuelva la salud a los gnomos envenenados. En {link:ironforge}Forjaz{/link}, los manitas de {link:gnomeregan}Gnomeregan{/link} envían a valientes forasteros de vuelta a la ciudad para rescatar su saber perdido. El Manitas Mayor {link:gelbin-mekkatorque}Gelbin Mekkatorque{/link} jura que su pueblo recuperará su hogar del traidor que lo ocupa.]=],
		},
	},
})

Translate("esMX", "sten-stoutarm", {
	title = "Sten Stoutarm",
	subtitle = "Proveedor de Crestanevada",
	found = "Ante las puertas de Yunquemar",
	hint = [=[Hable con el enano que recibe a los recién llegados a las puertas de Yunquemar.]=],
	allegiance = "Reino de Forjaz",
	aliases = { "Stoutarm" },
	sections = {
		{
			title = "Resumen",
			text = [=[Sten Stoutarm monta guardia a las puertas de Yunquemar y recibe a quienes llegan a {link:coldridge-valley}Crestanevada{/link} para servir. Tiene una manera práctica de darles la bienvenida. Un par de guantes de abrigo es su primer regalo, y carne de lobo es su precio. En un valle tan frío, calcula, es mejor perder una mañana de caza que un dedo.]=],
		},
		{
			title = "Importancia",
